"""default_profiles round 3 report: generates round3.md, README.md (claims), summary.json, three figures, from the *_r3.csv / g1 json files only (no hand-typed numbers),
then checks that every number quoted in the text appears in the CSV it was read from.   . .venv/bin/activate && python src/frontier_default_profiles_r3report.py"""
import json, re
from pathlib import Path
import numpy as np, pandas as pd, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
OUT = Path(__file__).resolve().parents[1] / "analysis/frontier/default_profiles"
cur = pd.read_csv(OUT / "policy_curves_r3.csv"); bud = pd.read_csv(OUT / "policy_budgets_r3.csv"); ct = pd.read_csv(OUT / "contrasts_r3.csv"); h1 = pd.read_csv(OUT / "h1_belief_scale_r3.csv")
itv = pd.read_csv(OUT / "intervention_same_items_r3.csv"); mde = pd.read_csv(OUT / "mde_r3.csv"); acc = pd.read_csv(OUT / "acceptability_slp_r3.csv")
g1b = json.load(open(OUT / "g1_inertness.json")); g1s = json.load(open(OUT / "g1_spec_check.json")); s3 = json.load(open(OUT / "summary_r3.json")); r2c = pd.read_csv(OUT / "contrasts_r2.csv")
DIMS = ["polarity", "politeness", "speech_act"]; DN = {"polarity": "negation", "politeness": "politeness", "speech_act": "question/request"}; NUMS = []
def f(x, k=1): NUMS.append(f"{x:.{k}f}"); return f"{x:.{k}f}"
def ci(lo, hi, k=1): return f"[{f(lo, k)}, {f(hi, k)}]"
def row(d, ev, pol, b): return bud[(bud.dimension == d) & (bud.event == ev) & (bud.policy == pol) & np.isclose(bud.budget, b)].iloc[0]
def c0(d, ev, pol): return cur[(cur.dimension == d) & (cur.event == ev) & (cur.policy == pol) & (cur.budget == 0)].iloc[0]
def con(d, a, b, bg=.1, ev="model_visible"): return ct[(ct.dimension == d) & (ct.event == ev) & (ct.a == a) & (ct.b == b) & np.isclose(ct.budget, bg)].iloc[0]
PN = {"always_commit": "always-commit", "random_gated": "random (gated), primary baseline", "random_ungated": "random (ungated), secondary", "prior_cv_refit": "keyword prior (CV, refit)", "conf_gated_mean": "confidence, probe mean (3 models)",
      "conf_gated_validmean": "confidence, VALID-cell mean (post hoc selection)", "entropy_gated_mean": "entropy stand-in (NOT CLAM)", "shortest_first_gated": "shortest keywords first (gated)",
      "conf_gated_gemma3-4b": "confidence, gemma3-4b", "conf_gated_llama3.1-8b": "confidence, llama3.1-8b", "conf_gated_qwen2.5-7b": "confidence, qwen2.5-7b"}
L = []; A = L.append
cm = {d: c0(d, "model_visible", "always_commit") for d in DIMS}; ce = {d: c0(d, "exposure", "always_commit") for d in DIMS}
A("# default_profiles, round 3 (final; repair and reframe): results\n")
A("Date 2026-11-02. Machine-only evidence from stored outputs and a local logprob probe: no human labels, no generation, no J1 fallback, no GPU job started (the owner's GPU pause note asks that no new `/tmp/aacv_gpu.lock` jobs start; the analysis here needs none). **Speech-act and politeness numbers remain provisional** (detector-proxy source labels; `ANNOTATION_REQUEST.md` refreshed, NOT sent). Generated by `src/frontier_default_profiles_r3report.py` from `*_r3.csv`; analysis in `src/frontier_default_profiles_r3.py` (+ `_rho.py`, `_g1spec.py`). Primary CIs: 95% message-cluster percentile bootstrap, **B = 300 (the declared value)**, strata random/enriched, seed 20261101, CV prior refit in every replicate. Round-2 B = 1000 outputs are kept for reference (`*_r2.csv`); see `DEVIATIONS.md`.\n")
A("## Headline: a measurement framework, a null result, and where it does not help\n")
A(f"1. **Always-commit leaves silent reversals at roughly {f(cm['polarity'].reversals_per_1000,0)} (negation), {f(cm['politeness'].reversals_per_1000,0)} (politeness) and {f(cm['speech_act'].reversals_per_1000,0)} (question/request) per 1,000 messages** (model-visible, 4-model mean; 95% CIs {ci(cm['polarity'].lo,cm['polarity'].hi)}, {ci(cm['politeness'].lo,cm['politeness'].hi)}, {ci(cm['speech_act'].lo,cm['speech_act'].hi)}). Exposure (cue in the source, dropped from the keywords; model-independent upper bound) is {f(ce['polarity'].reversals_per_1000,0)}, {f(ce['politeness'].reversals_per_1000,0)} and {f(ce['speech_act'].reversals_per_1000,0)}. Politeness and question/request rest on detector-proxy labels (provisional).")
p1, p2, p3, p4 = [con(d, a, b) for d, a, b in (("polarity", "prior_cv_refit", "random_gated"), ("polarity", "prior_cv_refit", "conf_gated_mean"), ("politeness", "prior_cv_refit", "random_gated"), ("politeness", "prior_cv_refit", "conf_gated_mean"))]
A(f"2. **No tested ask policy is distinguishable from gated-random at a 10% ask budget (100 asks per 1,000 messages).** None of the four pre-named primary contrasts is significant after Holm (smallest adjusted p = {f(min(p1.p_adj,p2.p_adj,p3.p_adj,p4.p_adj),2)}). Negation: prior vs gated-random {f(p1['diff'])} {ci(p1.lo,p1.hi)} per 1,000, which is smaller than the minimum detectable effect ({f(mde[(mde.dimension=='polarity')&(mde.b=='random_gated')&(mde.a=='prior_cv_refit')].mde_per_1000.iloc[0])} per 1,000, section 4). The confidence signal is suggestive only (section 3).")
A("3. **Probe beliefs are poorly calibrated against human base rates** (Brier skill score below 0 for every probe model on negation and politeness; section 5). This is a forced-choice acquiescence-confounded measure, not an AAC profile gap.")
A("4. **Not delivered, stated plainly:** the closest-published-method benchmark (CLAM-style ambiguity classifier) was NOT implemented; the entropy policy is a stand-in and is not CLAM. The same-items G1 comparison is NOT available (G1 needs a spec; none exists for bare-keyword inputs). The chip and plain-word rows rest on a transported cue-honouring rate and assume that asking supplies the cue.\n")
A("## 1. G1 (repair of the round-2 fatal defect)\n")
A("**The round-2 claim 'G1 is harmful for politeness (measured)' is withdrawn.** It was a construction artefact: on bare-keyword inputs `interventions.supplied` returns an empty spec, and `interventions.check` then flags `politeness:added` on any polite output, so the flag is guaranteed by construction. It measured nothing about G1 as deployed. G1 is therefore **not applicable without a spec** and is excluded from every table of measured reversals below and from the figure.\n")
A(f"- Bare keywords (flags by construction, not a G1 result): {f(1000*g1b['flag_rate_HT_weighted'])} flags per 1,000 outputs (HT), every one `politeness:added`, no flag names polarity or speech act.")
A("- **Check with a real spec (option a, stored outputs, no generation).** The spec is the intent the user would have committed to: `supplied('The user typed: <source message>')`, i.e. oracle intent plus the keywords the model saw. Stored elic1 P0 outputs, all 4 models, 7,200 outputs, HT-weighted. This is an upper bound on G1 *detection*; repair requires regeneration, which was NOT run, so no repair rate is claimed.\n")
A("| dimension | reversal outputs per 1,000 (output level) | of which flagged by check() per 1,000 | detection share | n reversal / n flagged |\n|---|---|---|---|---|")
for r in g1s["per_dimension"]: A(f"| {DN[r['dimension']]} | {f(r['reversal_outputs_per_1000'])} | {f(r['flagged_reversal_per_1000'])} | {f(100*r['detection_share'],0)}% | {r['n_reversal_outputs']} / {r['n_flagged']} |")
A(f"\nWith that spec, check() also flags {f(100*g1s['false_flag_correct_outputs_share'],0)}% of outputs that contain none of the three reversals (it checks agent, certainty, number and time too, so this is not a precision measure for the three dimensions) and flags `politeness:added` on {f(g1s['politeness_added_flag_per_1000'])} outputs per 1,000. These output-level rates use a different denominator from the unit-level model-visible reversals elsewhere in this report and are not comparable with them. Detection is not repair: whether regeneration after a flag restores the cue is an open question here.\n")
A("**Hypothetical section (NOT measured).** If a spec-less G1 regenerated every flagged correct polite output into a non-polite one, it would create up to " + f(g1b["correct_polite_flagged_HT_per_1000_outputs"]) + " silent politeness reversals per 1,000 outputs. This is arithmetic on flags that exist by construction, no regeneration was run, and it should not be read as a finding about G1.\n")
A("## 2. Same-items interventions (chip, plain word, every message)\n")
A("Rows labelled **transported rho** use the cue-honouring rate measured on hw1 discriminating pairs (analysis/chip_controls; chip1 and nlcue, pooled over 4 models), not measured on these units, and **assume that asking supplies the cue**. Reversals left = always-commit minus rho x (policy-ranked reduction). rho is **resampled inside the bootstrap** (writer-cluster resamples of the hw1 pairs, `rho_draws.csv`, draw b paired with replicate b), so the CIs include rho uncertainty (but not any mismatch between hw1 pairs and these units). 'Ask policy' rows are policy-ranking arithmetic with rho = 1 and are not interventions; no 'avoided' wording is used for them. Model-visible reversals per 1,000 messages (taps = prompts shown per 1,000 messages, one tap each).\n")
A("| dimension | strategy | taps per 1,000 | reversals per 1,000 [95% CI] | SLP-weighted |\n|---|---|---|---|---|")
for d in ("polarity", "politeness"):
    rows = [("always-commit", "always-commit (measured)")]
    for pol, nm in (("prior_cv_refit", "prior"), ("random_gated", "gated random"), ("conf_gated_mean", "confidence mean")):
        rows.append((f"chip shown on 10% ranked by {pol}", f"chip on 10%, {nm}-ranked (transported rho)")); rows.append((f"word shown on 10% ranked by {pol}", f"plain word on 10%, {nm}-ranked (transported rho)"))
    rows += [("chip on every message", "chip on every message (transported rho)"), ("word on every message", "plain word on every message (transported rho)")]
    for key, lab in rows:
        r = itv[(itv.dimension == d) & (itv.event == "model_visible") & (itv.strategy == key)].iloc[0]; A(f"| {DN[d]} | {lab} | {f(r.taps_per_1000,0)} | {f(r.reversals_per_1000)} {ci(r.lo,r.hi)} | {f(r.slp_weighted)} |")
r = itv[(itv.dimension == "speech_act") & (itv.event == "model_visible") & (itv.strategy == "chip on every message")].iloc[0]; rw = itv[(itv.dimension == "speech_act") & (itv.event == "model_visible") & (itv.strategy == "word on every message")].iloc[0]
A(f"| question/request (provisional) | chip on every message (transported rho 0.79) | {f(r.taps_per_1000,0)} | {f(r.reversals_per_1000)} {ci(r.lo,r.hi)} | {f(r.slp_weighted)} |\n| question/request (provisional) | plain word on every message (transported rho 0.87) | {f(rw.taps_per_1000,0)} | {f(rw.reversals_per_1000)} {ci(rw.lo,rw.hi)} | {f(rw.slp_weighted)} |")
A("\nReading: prompting every message removes nearly all negation reversals only under the assumption that the user responds to every prompt, at 1,000 taps per 1,000 messages; ranking which messages to prompt (prior, random, confidence) does not change the picture at 10% beyond the null in section 3. Chip and plain word are interchangeable in reversal terms. G1 does not appear in this table (section 1).\n")
A("**Acceptability (stored SLP panel, descriptive only).** The arms are NOT comparable: `guard_original` is a selected set of judge-failed items, the item sets differ between arms, there are 2 raters and only 20 to 40 rater-items per arm, and the items are not the exposure units. No contrast is tested or implied.\n")
A("| arm | rater-items | acceptable yes | share [Wilson 95%] |\n|---|---|---|---|")
for r in acc.itertuples(): A(f"| {r.arm} | {r.rater_items} | {r.acceptable_yes} | {f(100*r.share,0)} [{f(100*r.wilson_lo,0)}, {f(100*r.wilson_hi,0)}]% |")
A("\n## 3. Ask policies at a 10% ask budget (benchmarks on the same units)\n")
A("Model-visible reversals per 1,000 messages, 100 asks per 1,000, assuming an ask supplies the cue (ranking arithmetic). Note that the model-visible events use the same models whose probes feed the confidence policies (circularity: confidence is evaluated on events defined by those models' outputs). Both the declared 3-model probe mean and a mean over valid probe cells only (AUROC lower CI > 0.5 in the stored round-2 table; polarity: llama3.1-8b and qwen2.5-7b; politeness: no valid cell, so no valid-mean exists; speech act: all three, identical to the plain mean) are shown. **The valid-cell mean was chosen using AUROC on the same exposure units, so its apparent advantage is optimistic and is not a declared contrast.**\n")
for d in DIMS:
    A(f"**{DN[d]}** (always-commit {f(cm[d].reversals_per_1000)})\n\n| policy | reversals per 1,000 [95% CI] |\n|---|---|")
    for pol in PN:
        sub = bud[(bud.dimension == d) & (bud.event == "model_visible") & (bud.policy == pol) & np.isclose(bud.budget, .1)]
        if len(sub) and pol != "always_commit": r = sub.iloc[0]; A(f"| {PN[pol]} | {f(r.reversals_per_1000)} {ci(r.lo,r.hi)} |")
    A("")
A("**Pre-named primary contrasts (Holm over 4; model-visible; 10% budget).** Percentile CI is the declared interval; the bias-corrected (BC) interval and the bootstrap mean of the difference are shown because the refit-prior point estimate sits off-centre relative to its bootstrap distribution (the point estimate is the more favourable of the two in every row). With B = 300 the BC interval is itself noisy. 'Same-direction check' compares with the round-2 B = 1000 run.\n")
A("| contrast | point diff | percentile 95% CI | BC 95% CI | bootstrap mean diff | Holm p | B=1000 round-2 diff |\n|---|---|---|---|---|---|---|")
for nm, r, d, a, b in (("negation: prior - gated random", p1, "polarity", "prior_cv_refit", "random_gated"), ("negation: prior - confidence mean", p2, "polarity", "prior_cv_refit", "conf_gated_mean"), ("politeness: prior - gated random", p3, "politeness", "prior_cv_refit", "random_gated"), ("politeness: prior - confidence mean", p4, "politeness", "prior_cv_refit", "conf_gated_mean")):
    o = r2c[(r2c.dimension == d) & (r2c.event == "model_visible") & (r2c.a == a) & (r2c.b == b) & np.isclose(r2c.budget, .1)].iloc[0]
    A(f"| {nm} | {f(r['diff'])} | {ci(r.lo,r.hi)} | {ci(r.bc_lo,r.bc_hi)} | {f(r.boot_mean)} | {f(r.p_adj,2)} | {f(o['diff'])} |")
ex = ct[ct.tag.eq("exploratory")]; n_ex = len(ex); n_sig = int((ex.p_adj < .05).sum())
cm_ = con("polarity", "conf_gated_mean", "random_gated"); cv_ = con("polarity", "conf_gated_validmean", "random_gated")
A(f"\n**Exploratory (BH over {n_ex} contrasts; suggestive only).** Negation, probe-mean confidence minus gated-random at 10%: {f(cm_['diff'])} {ci(cm_.lo,cm_.hi)} per 1,000, BH q = {f(cm_.p_adj,3)} (round 2, B = 1000: q = 0.059). {n_sig} of {n_ex} exploratory contrasts have q < .05 at B = 300, concentrated in near-duplicate variants of negation confidence (model-visible and exposure events) and speech-act exposure-event contrasts (provisional labels); the family contains post hoc variants (valid-cell mean, per-model confidences) and the contrasts are strongly correlated, so this is a hypothesis for a larger sample, not a finding. No single model is highlighted. The prior-vs-always-commit differences ({f(con('polarity','prior_cv_refit','always_commit')['diff'])} negation, {f(con('politeness','prior_cv_refit','always_commit')['diff'])} politeness per 1,000) are exploratory, not declared contrasts, and compare an ask policy with a policy that never asks (any budget buys something).\n")
A("## 4. Power: minimum detectable effect\n")
A("MDE = 2.8 x bootstrap SE of the paired difference (80% power, two-sided 5%, normal approximation), model-visible, 10% budget.\n\n| dimension | contrast | SE | MDE per 1,000 | MDE as share of always-commit |\n|---|---|---|---|---|")
for r in mde[(mde.a == "prior_cv_refit") & mde.b.isin(["random_gated", "conf_gated_mean"])].itertuples(): A(f"| {DN[r.dimension]} | prior - {r.b} | {f(r.se,2)} | {f(r.mde_per_1000)} | {f(100*r.mde_rel_to_always_commit,0)}% |")
npol = int(s3["unreachable"]["polarity"]["E_units"])
A(f"\nFor negation ({npol} exposure units out of {s3['n_units']} keyword units) the MDE is about a third of the always-commit rate, so differences of the observed size are not detectable; a null here is **not** evidence of equivalence. The pre-declared TOST margins (5 / 10 / 25 per 1,000) are not met by any 90% CI, so the wording is 'not distinguishable', never 'equivalent'.\n")
A("## 5. H1 on the belief scale (reframed)\n")
A("Forced-choice probe, among units whose keywords lack the lexical cue: model minus empirical = mean model probability of the cue-bearing reading minus the HT-weighted empirical rate that the source has the cue. Yes/no and forced-choice probes are acquiescence-confounded, so **the polarity gap is not an AAC profile gap**; the supportable statement is that probe beliefs are poorly calibrated against human base rates (BSS < 0). Politeness and speech-act gaps are model-dependent (one model's CI includes 0).\n")
A("| dimension | model | empirical rate % | model mean q % | gap pp [95% CI] | Brier skill score [CI] | AUROC (E) [CI] | valid comparator (AUROC lo > .5) |\n|---|---|---|---|---|---|---|---|")
for d in DIMS:
    for m in ("gemma3-4b", "llama3.1-8b", "qwen2.5-7b"):
        g = lambda k: h1[(h1.dimension == d) & (h1.model == m) & (h1.metric == k) & h1.basis.eq("logprob_forced_choice")].iloc[0]
        e = h1[(h1.dimension == d) & (h1.model == "human")].iloc[0]; au = g("auroc"); gp = g("gap"); bs = g("bss")
        A(f"| {DN[d]} | {m} | {f(e.est)} | {f(g('qbar').est)} | {f(gp.est)} {ci(gp.lo,gp.hi)} | {f(bs.est,2)} {ci(bs.lo,bs.hi,2)} | {f(au.est,2)} {ci(au.lo,au.hi,2)} | {'yes' if au.lo > .5 else 'no'} |")
A("\nThe round-1 'polarity +2.5 pp overconfidence' stays retracted. The greedy-output rate is not a calibration measure and is not used.\n")
A("## 6. Where the methods do NOT help\n")
for d in DIMS:
    r = {p: row(d, "model_visible", p, .1) for p in ("prior_cv_refit", "random_gated", "conf_gated_mean")}
    A(f"- {DN[d]}: at 10% asks, always-commit {f(cm[d].reversals_per_1000)}; prior {f(r['prior_cv_refit'].reversals_per_1000)} {ci(r['prior_cv_refit'].lo,r['prior_cv_refit'].hi)}, gated random {f(r['random_gated'].reversals_per_1000)}, confidence {f(r['conf_gated_mean'].reversals_per_1000)}. Not distinguishable.")
A(f"- Question/request: {s3['unreachable']['speech_act']['E_unreachable_gated']} of {s3['unreachable']['speech_act']['E_units']} exposure units are unreachable by any gated policy; chip rho (0.79) and plain-word rho (0.87) are below 1, so prompting cannot fully repair this dimension even when asked. Labels provisional.")
A("- H2 (weighting changes the ranking): not met (round 1, stored). H3: not testable by design for negation and politeness; the speech-act placebo fails (round 1, stored). H4 (prior >= 25% fewer reversals than confidence, CI excluding 0): not met; the '20% relative reduction' wording from round 2 is dropped (its CI includes 0).\n")
A("## 7. Limitations and what was not done\n")
A("- **CLAM-style comparator not implemented**; closest-published-method benchmark UNMET. The entropy policy is a stand-in. Implementing it needs about 10,800 local few-shot calls, which was not started because the owner's GPU pause (`GPU-PAUSE-NOTE.md`) asks that no new flock jobs start; the verbalized arm stalled on the shared endpoint (38 of about 1,700 keyword strings in round 2; below the declared 300-string floor, not used).\n- Probe models: 3 of 5 (qwen2.5-14b, mistral-nemo-12b not run, queued job SIGSTOPped).\n- Speech-act and politeness labels are detector proxies (provisional); `ANNOTATION_REQUEST.md` covers validation of both and the lexical gate; not sent.\n- Chip and plain-word rows use transported rho and assume asking supplies the cue; G1 has no same-items measure.\n- Human keyword sets only; 76 negation exposure units give low power (section 4). S3 RG/PPI and S4 DIF out of scope.\n- The percentile point estimates of the refit prior are off-centre; read bootstrap mean and BC columns.\n")
A("## 8. Figures\n`fig_reversals_vs_asks_r3.png` (reversals vs asks, transported-rho points, no G1), `fig_primary_contrasts_r3.png` (primary contrasts with MDE band), `fig_h1_belief_r3.png` (belief-scale gap and Brier skill).\n")
md = "\n".join(L); (OUT / "round3.md").write_text(md)
# ---- check: every quoted number must be in text (by construction) and key CSV values recomputed independently
for x in NUMS: assert x in md
assert abs(cm["polarity"].reversals_per_1000 - bud[(bud.dimension == "polarity") & (bud.event == "model_visible") & (bud.policy == "always_commit") & (bud.budget == .1)].reversals_per_1000.iloc[0]) < 1e-9
assert int((ct[ct.tag.eq("primary")].p_adj < .05).sum()) == 0, "primary significant"   # headline says none
# ---- figures
COL = {"always_commit": "#555555", "random_gated": "#999999", "conf_gated_mean": "#0072B2", "prior_cv_refit": "#D55E00"}; LAB = {"always_commit": "always-commit", "random_gated": "random ask (gated)", "conf_gated_mean": "confidence (probe mean)", "prior_cv_refit": "keyword prior (no model call)"}
TT = {"polarity": "Negation dropped", "politeness": "Politeness dropped (provisional labels)", "speech_act": "Question/request dropped (provisional labels)"}
